<script setup>
import { computed, onMounted, ref } from 'vue'
const props=defineProps({total:Number}),emit=defineEmits(['close','complete']),step=ref(1),phone=ref(''),loading=ref(false),error=ref('')
const form=ref({firstName:'',lastName:'',street:'',unit:'',city:'',state:'Delhi',pin:''})
const amount=computed(()=>props.total+59),deliveryAddress=computed(()=>`${form.value.firstName} ${form.value.lastName}, ${form.value.street}, ${form.value.unit}, ${form.value.city}, ${form.value.state} ${form.value.pin}`)
const addressComplete=computed(()=>form.value.firstName&&form.value.lastName&&form.value.street&&form.value.city&&form.value.state&&/^\d{6}$/.test(form.value.pin))
const phoneComplete=computed(()=>phone.value.replace(/\D/g,'').length>=10)
const canOpenStep=target=>target<=step.value||(target===2&&phoneComplete.value)||(target===3&&phoneComplete.value&&addressComplete.value)
onMounted(()=>{const back=document.querySelector('.checkout-back'),checkout=document.querySelector('.checkout');if(back){back.style.width='32px';back.style.height='32px';back.style.padding='0';back.style.display='grid';back.style.placeItems='center';back.style.fontSize='20px'}const heading=checkout?.querySelector('header .eyebrow');if(heading)heading.style.marginLeft='28px';const cleanShipping=()=>{checkout?.querySelectorAll('.shipping,main>p').forEach(node=>{if(node.classList.contains('shipping')||node.textContent.includes('total includes'))node.remove()})};cleanShipping();new MutationObserver(cleanShipping).observe(checkout,{childList:true,subtree:true});const summary=checkout?.querySelector('.checkout-summary');if(summary){summary.insertAdjacentHTML('afterbegin','<span class="summary-cart">🛒</span>');summary.insertAdjacentHTML('beforeend','<span class="summary-arrow">⌄</span>');const details=document.createElement('div'),quantity=Math.max(1,Math.round(props.total/120));details.className='summary-details';details.innerHTML=`<span>Protein Choco Crunch × ${quantity}<b>₹${props.total}</b></span><span>Shipping<b>₹59</b></span>`;summary.after(details);summary.style.cursor='pointer';summary.addEventListener('click',()=>details.classList.toggle('open'))}document.querySelector('.checkout-steps')?.addEventListener('click',event=>{const label=event.target.textContent||'',target=label.startsWith('3.')?3:label.startsWith('2.')?2:1;if(!canOpenStep(target)){event.stopImmediatePropagation();event.preventDefault()}},true)})
const goBack=()=>step.value===1?emit('close'):step.value--
const request=async(path,options={})=>{const response=await fetch(path,{credentials:'same-origin',headers:{'Content-Type':'application/json'},...options}),data=await response.json();if(!response.ok)throw new Error(data.error||'Something went wrong.');return data}
const pay=async()=>{loading.value=true;error.value='';try{const checkout=await request('/api/orders/checkout/create',{method:'POST'});if(!window.Razorpay)await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://checkout.razorpay.com/v1/checkout.js';script.onload=resolve;script.onerror=reject;document.head.appendChild(script)});new window.Razorpay({key:checkout.keyId,amount:checkout.amount,currency:checkout.currency,name:'RAWR',description:'Protein Choco Crunch',order_id:checkout.orderId,prefill:{contact:phone.value},theme:{color:'#f15a24'},handler:async response=>{try{await request('/api/orders/checkout/verify',{method:'POST',body:JSON.stringify({...response,phone:phone.value,address:deliveryAddress})});emit('complete')}catch(e){error.value=e.message}finally{loading.value=false}},modal:{ondismiss:()=>loading.value=false}}).open()}catch(e){error.value=e.message;loading.value=false}}
</script>
<template><div class="checkout-overlay"><section class="checkout"><button class="checkout-back" aria-label="Back" @click="goBack">←</button><button class="checkout-close" @click="emit('close')">×</button><header><p class="eyebrow">Secure checkout</p><div class="checkout-steps"><button :class="{active:step===1,done:step>1}" @click="step=1">1. Mobile</button><i></i><button :class="{active:step===2,done:step>2}" @click="step=2">2. Address</button><i></i><button :class="{active:step===3}" @click="step=3">3. Pay</button></div></header><div class="checkout-summary"><span>Order summary</span><b>₹{{amount}}</b></div><main><template v-if="step===1"><h2>Where can we reach you?</h2><p>We'll send order updates to this number.</p><label>Mobile number<input v-model="phone" inputmode="tel" placeholder="10-digit mobile number"></label><button class="button primary" :disabled="phone.replace(/\D/g,'').length<10" @click="step=2">Continue →</button></template><template v-else-if="step===2"><h2>Delivery address</h2><p>Tell us where to send your RAWR order.</p><div class="address-form"><input v-model="form.firstName" placeholder="First name"><input v-model="form.lastName" placeholder="Last name"><input v-model="form.street" class="wide" placeholder="Address"><input v-model="form.unit" class="wide" placeholder="Apartment, suite, etc. (optional)"><input v-model="form.city" placeholder="City"><select v-model="form.state"><option>Delhi</option><option>Haryana</option><option>Uttar Pradesh</option><option>Maharashtra</option><option>Karnataka</option></select><input v-model="form.pin" inputmode="numeric" maxlength="6" placeholder="PIN code"></div><p class="shipping">Standard shipping <b>₹59</b></p><button class="button primary" :disabled="!addressComplete" @click="step=3">Continue →</button></template><template v-else><h2>Payment</h2><p>Your total includes ₹59 standard shipping.</p><div class="razorpay-card"><span>R</span><div><b>Razorpay</b><small>Cards, UPI, netbanking & wallets</small></div><strong>₹{{amount}}</strong></div><p v-if="error" class="error">{{error}}</p><button class="button primary" :disabled="loading" @click="pay">{{loading?'Opening Razorpay…':'Pay securely with Razorpay'}}</button></template></main></section></div></template>
<style scoped>.checkout-overlay{position:fixed;z-index:50;inset:0;background:rgba(0,0,0,.72);display:grid;place-items:center;padding:20px}.checkout{position:relative;width:min(560px,100%);background:#151617;border:1px solid #343537;box-shadow:0 30px 80px rgba(0,0,0,.5)}header{padding:28px 40px 20px;border-bottom:1px solid #343537}.checkout-steps{display:flex;align-items:center;gap:9px;margin-top:14px}.checkout-steps i{height:1px;flex:1;background:#444}.checkout-steps button{background:none;border:0;padding:0;color:#777;font:inherit;font-size:.74rem;cursor:pointer;white-space:nowrap}.checkout-steps button.active{color:#f15a24}.checkout-steps button.done{color:#85bd7a}.checkout-close,.checkout-back{position:absolute;top:14px;background:none;border:0;color:#aaa;font-size:2rem;cursor:pointer}.checkout-close{right:17px}.checkout-back{left:17px}.checkout-summary{margin:20px 24px 0;padding:17px;border:1px solid #343537;display:flex;justify-content:space-between}.checkout-summary b,.razorpay-card strong{color:#f15a24}main{padding:28px 32px 34px}main h2{margin:0 0 7px;font-size:1.7rem}main>p{color:#aaa;line-height:1.5;margin:0 0 24px}label{display:grid;gap:8px;color:#ccc;font-size:.78rem}input,textarea,select{background:#101112;border:1px solid #444547;color:#fff;padding:14px;font:inherit;min-width:0}.checkout .button{width:100%;margin-top:28px}.checkout .button:disabled{opacity:.45}.address-form{display:grid;grid-template-columns:1fr 1fr 1fr;gap:11px}.address-form .wide{grid-column:1/-1}.shipping{display:flex;justify-content:space-between;margin:18px 0 0!important}.shipping b{color:#f15a24}.razorpay-card{display:flex;align-items:center;gap:12px;border:1px solid #f15a24;padding:16px}.razorpay-card>span{background:#f15a24;color:#111;width:33px;height:33px;display:grid;place-items:center;font-weight:900}.razorpay-card div{display:grid;gap:3px}.razorpay-card small{color:#aaa}.razorpay-card strong{margin-left:auto}.error{color:#ff7755}@media(max-width:480px){.checkout{max-height:calc(100vh - 28px);overflow:auto}header,main{padding-left:22px;padding-right:22px}.checkout-steps button{font-size:.63rem}.address-form{grid-template-columns:1fr 1fr}.address-form input:nth-last-child(-n+3),.address-form select{grid-column:auto}.address-form input:last-child{grid-column:1/-1}}</style>
